import{_ as t,o,c as s,ag as a}from"./chunks/framework.DB9Ll7VW.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Diagnose and fix the most common Sikshya LMS issues — REST 404s, permalinks, gateway sandbox mode, email deliverability, role / capability oddities, cache plugins, and PHP fatals.","frontmatter":{"title":"Troubleshooting","description":"Diagnose and fix the most common Sikshya LMS issues — REST 404s, permalinks, gateway sandbox mode, email deliverability, role / capability oddities, cache plugins, and PHP fatals."},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1778327862000}'),n={name:"troubleshooting.md"};function r(i,e,l,p,c,d){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This page lists the issues we see most often and the fastest way through them.</p><h2 id="rest-returns-404-nothing-loads-in-the-admin" tabindex="-1">&quot;REST returns 404 / nothing loads in the admin&quot; <a class="header-anchor" href="#rest-returns-404-nothing-loads-in-the-admin" aria-label="Permalink to &quot;&quot;REST returns 404 / nothing loads in the admin&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> The admin React shell shows blank panels; the network tab shows <code>404</code> for <code>/wp-json/sikshya/v1/...</code>.</p><p><strong>Cause:</strong> Pretty permalinks are off, or a security plugin is blocking REST.</p><p><strong>Fix:</strong></p><ol class="step-list"><li>Go to <span class="screen-path">Settings → Permalinks</span>. Pick <strong>Post name</strong> (or any non-Plain). Click <strong>Save Changes</strong>.</li><li>Visit <code>/wp-json/sikshya/v1/</code> in a browser. You should see JSON, not 404.</li><li>If you have <strong>Wordfence</strong>, <strong>iThemes Security</strong>, etc., temporarily allow <code>wp-json</code> for your IP.</li></ol><h2 id="permalinks-404-on-the-front-of-the-site" tabindex="-1">&quot;Permalinks 404 on the front of the site&quot; <a class="header-anchor" href="#permalinks-404-on-the-front-of-the-site" aria-label="Permalink to &quot;&quot;Permalinks 404 on the front of the site&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> <code>/courses/</code>, <code>/cart/</code>, <code>/checkout/</code>, <code>/my-learning/</code> all return 404.</p><p><strong>Fix:</strong> Open <span class="screen-path">Settings → Permalinks</span> and click <strong>Save Changes</strong> (no need to change anything; saving flushes rewrite rules). Or run <code>wp rewrite flush</code> via WP-CLI.</p><h2 id="stripe-doesn-t-show-up-under-settings-→-payment-pro" tabindex="-1">&quot;Stripe doesn&#39;t show up under Settings → Payment&quot; <span class="pro-pill">PRO</span> <a class="header-anchor" href="#stripe-doesn-t-show-up-under-settings-→-payment-pro" aria-label="Permalink to &quot;&quot;Stripe doesn&#39;t show up under Settings → Payment&quot; &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><p><strong>Symptom:</strong> PayPal is listed, but you can&#39;t find Stripe — or you see only an &quot;Upgrade to enable&quot; prompt where Stripe should appear.</p><p><strong>Cause:</strong> <strong>Stripe is a Pro-only add-on</strong> — it isn&#39;t bundled with the free Sikshya plugin. The gateway list under <span class="screen-path">Settings → Payment</span> only contains the gateways your Pro license unlocks.</p><p><strong>Fix:</strong></p><ol class="step-list"><li>Install Sikshya Pro alongside the free plugin and activate your license under <span class="screen-path">Sikshya → License</span>.</li><li>Open <span class="screen-path">Sikshya → Add-ons</span>, find <strong>Stripe</strong>, and toggle it on.</li><li>Stripe now appears under <span class="screen-path">Sikshya → Settings → Payment</span> — paste your keys and webhook secret.</li></ol><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Unlock Stripe + 5 more gateways</span></div><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Compare Pro plans →</a></div><h2 id="paypal-webhook-shows-but-no-order-is-fulfilled" tabindex="-1">&quot;PayPal webhook shows but no order is fulfilled&quot; <a class="header-anchor" href="#paypal-webhook-shows-but-no-order-is-fulfilled" aria-label="Permalink to &quot;&quot;PayPal webhook shows but no order is fulfilled&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> PayPal logs show 200 from your site, but the order stays <strong>pending</strong>.</p><p><strong>Cause:</strong> Webhook ID mismatch (sandbox vs live), missing client id / secret, or REST routes blocked by security.</p><p><strong>Fix:</strong></p><ol class="step-list"><li>Open <span class="screen-path">Sikshya → Settings → Payment → PayPal</span>. Confirm <strong>Mode</strong> matches the webhook (sandbox vs live), and <strong>Webhook ID</strong> matches the PayPal dashboard.</li><li>Confirm REST is reachable — visit <code>/wp-json/sikshya/v1/webhooks/paypal</code> (you should get a 405 method-not-allowed for a GET, not a 403).</li><li>Check <span class="screen-path">Tools → Activity log</span> for webhook errors.</li></ol><h2 id="stripe-webhook-signature-mismatch" tabindex="-1">&quot;Stripe webhook signature mismatch&quot; <a class="header-anchor" href="#stripe-webhook-signature-mismatch" aria-label="Permalink to &quot;&quot;Stripe webhook signature mismatch&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> Stripe says webhook delivery failed; Sikshya logs say &quot;invalid signature&quot;.</p><p><strong>Cause:</strong> Webhook secret in Sikshya doesn&#39;t match Stripe&#39;s webhook signing secret.</p><p><strong>Fix:</strong></p><ol class="step-list"><li>In Stripe → <strong>Developers → Webhooks</strong> → click your endpoint → <strong>Reveal secret</strong> under <strong>Signing secret</strong> (<code>whsec_...</code>).</li><li>Paste it into <span class="screen-path">Sikshya → Settings → Payment → Stripe → Webhook secret</span>.</li><li>Save. Re-send a test event in Stripe.</li></ol><h2 id="emails-aren-t-arriving" tabindex="-1">&quot;Emails aren&#39;t arriving&quot; <a class="header-anchor" href="#emails-aren-t-arriving" aria-label="Permalink to &quot;&quot;Emails aren&#39;t arriving&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> No enrollment / receipt / completion emails reach the learner.</p><p><strong>Fix:</strong></p><ol class="step-list"><li>Install a transactional email plugin: <strong>WP Mail SMTP</strong>, <strong>FluentSMTP</strong>, or <strong>Post SMTP</strong>.</li><li>Connect to a transactional ESP: SendGrid, Postmark, Amazon SES, Mailgun.</li><li>Set <strong>From name</strong> and <strong>From email</strong> to a <code>noreply@</code> on your sending domain.</li><li>Configure <strong>SPF</strong>, <strong>DKIM</strong>, and <strong>DMARC</strong> on the From domain.</li><li>Test deliverability via <a href="https://www.mail-tester.com/">mail-tester.com</a>.</li></ol><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Professional email delivery</span></div><p class="pro-callout__desc">The Pro <strong>Professional email delivery &amp; branded templates</strong> add-on streamlines ESP setup with a guided UI and adds a branded multi-template kit.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya-lms/pricing/">Unlock branded delivery →</a></div><h2 id="apply-to-teach-doesn-t-grant-the-role" tabindex="-1">&quot;Apply to teach doesn&#39;t grant the role&quot; <a class="header-anchor" href="#apply-to-teach-doesn-t-grant-the-role" aria-label="Permalink to &quot;&quot;Apply to teach doesn&#39;t grant the role&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> A user submits the instructor application but doesn&#39;t get the <code>sikshya_instructor</code> role automatically.</p><p><strong>Cause:</strong> This is by design. Applications are recorded as <strong>pending</strong> — an admin must approve them.</p><p><strong>Fix:</strong> Go to <span class="screen-path">Sikshya → People → Applications</span> and click <strong>Approve</strong>.</p><h2 id="setup-wizard-never-finishes" tabindex="-1">&quot;Setup wizard never finishes&quot; <a class="header-anchor" href="#setup-wizard-never-finishes" aria-label="Permalink to &quot;&quot;Setup wizard never finishes&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> After activation, you can&#39;t get past the setup wizard.</p><p><strong>Fix:</strong></p><ol class="step-list"><li>Make sure your account has <code>manage_options</code>.</li><li>Disable WAF / Security plugins temporarily, run the wizard, re-enable.</li><li>If still stuck: open <span class="screen-path">Sikshya → Tools → Maintenance → Open setup wizard</span> to re-run.</li></ol><h2 id="i-deactivated-pro-and-lost-some-data" tabindex="-1">&quot;I deactivated Pro and lost some data&quot; <a class="header-anchor" href="#i-deactivated-pro-and-lost-some-data" aria-label="Permalink to &quot;&quot;I deactivated Pro and lost some data&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> After turning off Sikshya Pro, gradebook / drip / advanced certificates disappear.</p><p><strong>Cause:</strong> Pro features render only when their add-on is on. <strong>Stored data is preserved.</strong></p><p><strong>Fix:</strong> Re-enable the add-on under <span class="screen-path">Sikshya → Add-ons</span> to bring back the UI.</p><h2 id="course-content-shows-but-progression-is-locked" tabindex="-1">&quot;Course content shows but progression is locked&quot; <a class="header-anchor" href="#course-content-shows-but-progression-is-locked" aria-label="Permalink to &quot;&quot;Course content shows but progression is locked&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> A learner is enrolled but can&#39;t open the next lesson.</p><p><strong>Cause:</strong> Sequential progression is on (default in free) and a previous lesson hasn&#39;t been completed; or a Pro <strong>drip</strong> or <strong>prerequisite</strong> rule applies.</p><p><strong>Fix:</strong> Have the learner mark the current lesson complete. Or, as admin, manually mark lessons complete.</p><h2 id="cache-plugin-breaks-checkout-login" tabindex="-1">&quot;Cache plugin breaks checkout / login&quot; <a class="header-anchor" href="#cache-plugin-breaks-checkout-login" aria-label="Permalink to &quot;&quot;Cache plugin breaks checkout / login&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> Login form keeps showing logged-out state; checkout looks blank.</p><p><strong>Cause:</strong> Page cache is serving the logged-out version of a session-specific page.</p><p><strong>Fix:</strong> Exclude these from your page cache:</p><ul><li><code>/cart/</code>, <code>/checkout/</code>, <code>/my-learning/</code>, <code>/learn/</code>, <code>/order/</code>, <code>/login/</code></li><li><code>/wp-json/sikshya/v1/checkout/*</code>, <code>/wp-json/sikshya/v1/me/*</code></li></ul><h2 id="php-fatal-errors-after-enabling-pro" tabindex="-1">&quot;PHP fatal errors after enabling Pro&quot; <a class="header-anchor" href="#php-fatal-errors-after-enabling-pro" aria-label="Permalink to &quot;&quot;PHP fatal errors after enabling Pro&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> White screen of death right after activating Sikshya Pro.</p><p><strong>Cause:</strong> Mismatched plugin versions, or Pro was activated before Free.</p><p><strong>Fix:</strong></p><ol class="step-list"><li>Add <code>define(&#39;WP_DEBUG&#39;, true); define(&#39;WP_DEBUG_LOG&#39;, true);</code> to <code>wp-config.php</code>.</li><li>Re-read the error in <code>wp-content/debug.log</code>.</li><li>Update both plugins to the latest versions.</li><li>Activate Sikshya <strong>first</strong>, then Sikshya Pro.</li></ol><h2 id="i-m-on-a-case-sensitive-linux-host-and-templates-don-t-load" tabindex="-1">&quot;I&#39;m on a case-sensitive Linux host and templates don&#39;t load&quot; <a class="header-anchor" href="#i-m-on-a-case-sensitive-linux-host-and-templates-don-t-load" aria-label="Permalink to &quot;&quot;I&#39;m on a case-sensitive Linux host and templates don&#39;t load&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> A template override in your theme isn&#39;t picked up.</p><p><strong>Cause:</strong> macOS dev is case-insensitive; production Linux is case-sensitive. A template with the wrong case in the path silently fails.</p><p><strong>Fix:</strong> Match Sikshya&#39;s exact casing — <code>templates/single-course.php</code>, <code>templates/partials/courses/card.php</code>, etc.</p><h2 id="rest-returns-403-for-an-admin-user" tabindex="-1">&quot;REST returns 403 for an admin user&quot; <a class="header-anchor" href="#rest-returns-403-for-an-admin-user" aria-label="Permalink to &quot;&quot;REST returns 403 for an admin user&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> Admin REST routes return <code>rest_forbidden</code>.</p><p><strong>Cause:</strong> Cookie session expired, missing <code>X-WP-Nonce</code>, or a role plugin removed a capability.</p><p><strong>Fix:</strong></p><ol class="step-list"><li>Refresh the WordPress admin page (re-issues a fresh nonce).</li><li>Confirm your user has <code>manage_sikshya</code> and <code>sikshya_access_admin_app</code>.</li><li>Check that a role plugin (Members, User Role Editor) didn&#39;t remove those caps from administrator.</li></ol><h2 id="pro-license-shows-valid-in-mantrabrain-dashboard-but-sikshya-says-invalid" tabindex="-1">&quot;Pro license shows valid in Mantrabrain dashboard but Sikshya says invalid&quot; <a class="header-anchor" href="#pro-license-shows-valid-in-mantrabrain-dashboard-but-sikshya-says-invalid" aria-label="Permalink to &quot;&quot;Pro license shows valid in Mantrabrain dashboard but Sikshya says invalid&quot;&quot;">​</a></h2><p><strong>Symptom:</strong> Account dashboard says <strong>Active</strong>; <span class="screen-path">Sikshya → License</span> says invalid.</p><p><strong>Cause:</strong> License key activated on too many sites, or the site URL differs (<code>www.</code> mismatch).</p><p><strong>Fix:</strong></p><ol class="step-list"><li>Open the Mantrabrain account dashboard and confirm site limits.</li><li>Deactivate old / dev URLs.</li><li>Click <strong>Check status</strong> in <span class="screen-path">Sikshya → License</span>.</li></ol><h2 id="diagnostics-tools" tabindex="-1">Diagnostics tools <a class="header-anchor" href="#diagnostics-tools" aria-label="Permalink to &quot;Diagnostics tools&quot;">​</a></h2><ul><li><span class="screen-path">Sikshya → Tools → System status</span> — PHP, WP, server, plugin versions.</li><li><span class="screen-path">Sikshya → Tools → Maintenance</span> — clear cache, reset settings, import sample data.</li><li><span class="screen-path">Sikshya → Tools → Activity log</span> <span class="pro-pill">PRO</span> — webhook + email + general logs.</li></ul><h2 id="when-to-file-a-bug" tabindex="-1">When to file a bug <a class="header-anchor" href="#when-to-file-a-bug" aria-label="Permalink to &quot;When to file a bug&quot;">​</a></h2><p>Before filing, please:</p><ol class="step-list"><li>Update both Sikshya and Sikshya Pro to the latest.</li><li>Disable other plugins one by one to rule out conflicts.</li><li>Switch to a default theme briefly to rule out theme conflicts.</li><li>Capture the exact steps + a <code>WP_DEBUG</code> log of the error.</li></ol><p>Then <a href="https://github.com/MantraBrain" target="_blank" rel="noreferrer">file a bug on GitHub</a> (free) or open a <a href="https://mantrabrain.com/contact/" target="_blank" rel="noreferrer">priority support ticket</a> (Pro).</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/docs/installation">Installation</a></li><li><a href="/docs/payment-settings">Payments</a></li><li><a href="/docs/email-settings">Email &amp; notifications</a></li><li><a href="/docs/support">Support</a></li></ul>',79)])])}const g=t(n,[["render",r]]);export{u as __pageData,g as default};
